def compute(vars):
    start_balance = vars["v1"]
    end_balance = vars["v2"]
    net_change = end_balance - start_balance

    return {
        "value": net_change,
        "trace": {
            "start_balance": start_balance,
            "end_balance": end_balance,
            "net_change": net_change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
